torch::Tensor tall_skinny_matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

tall_skinny_matmul = load_inline(
    name="tall_skinny_matmul",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["tall_skinny_matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model using a custom CUDA kernel for the tall-and-skinny
    matrix multiplication C = A * B, where A is (M, K), B is (K, M),
    and K << M.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_fn = tall_skinny_matmul.tall_skinny_matmul_cuda

    def forward(self, A, B):
        A = A.cuda().contiguous()
        B = B.cuda().contiguous()
        return self.matmul_fn(A, B)


M = 16384 * 2
N = 16 * 2

def get_inputs():
    A = torch.rand(M, N)
    B = torch.rand(N, M)
    return [A, B]

