#include <cuda_runtime.h>
#define MAX_K 128
#define TILE_M 128
#define TILE_N 128
#define THREAD_TILE_M 8
#define THREAD_TILE_N 8
#define VEC 4
#define THREADS_X (TILE_N / THREAD_TILE_N)
#define THREADS_Y (TILE_M / THREAD_TILE_M)
#define NUM_THREADS (THREADS_X * THREADS_Y)
// Templated kernel: K is a compile-time constant (KT) when known at launch time,
// allowing the compiler to fully unroll the inner K-reduction loop and keep the
// A-tile row cached in registers, eliminating loop overhead and improving ILP
// for the tall-and-skinny GEMM where K is small and fixed.
template <int KT>
__global__ void tall_skinny_matmul_kernel_tpl(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M)
{
    extern __shared__ float smem[];
    float* sA = smem;                     // TILE_M x KT
    float* sB = smem + TILE_M * KT;       // KT x (TILE_N + 4)
    int row_base = blockIdx.x * TILE_M;
    int col_base = blockIdx.y * TILE_N;
    int tid = threadIdx.x;
    int tx = tid % THREADS_X;
    int ty = tid / THREADS_X;
    if (KT % VEC == 0) {
        const int k_groups = KT / VEC;
        for (int idx = tid; idx < TILE_M * k_groups; idx += NUM_THREADS) {
            int r = idx / k_groups;
            int kg = idx % k_groups;
            int global_row = row_base + r;
            if (global_row < M) {
                float4 avec = *reinterpret_cast<const float4*>(&A[global_row * KT + kg * VEC]);
                sA[r * KT + kg * VEC + 0] = avec.x;
                sA[r * KT + kg * VEC + 1] = avec.y;
                sA[r * KT + kg * VEC + 2] = avec.z;
                sA[r * KT + kg * VEC + 3] = avec.w;
            } else {
                sA[r * KT + kg * VEC + 0] = 0.0f;
                sA[r * KT + kg * VEC + 1] = 0.0f;
                sA[r * KT + kg * VEC + 2] = 0.0f;
                sA[r * KT + kg * VEC + 3] = 0.0f;
            }
        }
    } else {
        for (int idx = tid; idx < TILE_M * KT; idx += NUM_THREADS) {
            int r = idx / KT;
            int k = idx % KT;
            int global_row = row_base + r;
            sA[r * KT + k] = (global_row < M) ? A[global_row * KT + k] : 0.0f;
        }
    }
    const int col_groups = TILE_N / VEC;
    for (int idx = tid; idx < KT * col_groups; idx += NUM_THREADS) {
        int k = idx / col_groups;
        int cg = idx % col_groups;
        int col = col_base + cg * VEC;
        if (col + VEC - 1 < M) {
            float4 bvec = *reinterpret_cast<const float4*>(&B[k * M + col]);
            sB[k * (TILE_N + 4) + cg * VEC + 0] = bvec.x;
            sB[k * (TILE_N + 4) + cg * VEC + 1] = bvec.y;
            sB[k * (TILE_N + 4) + cg * VEC + 2] = bvec.z;
            sB[k * (TILE_N + 4) + cg * VEC + 3] = bvec.w;
        } else {
            #pragma unroll
            for (int c = 0; c < VEC; ++c) {
                int cc = col + c;
                sB[k * (TILE_N + 4) + cg * VEC + c] = (cc < M) ? B[k * M + cc] : 0.0f;
            }
        }
    }
    __syncthreads();
    float acc[THREAD_TILE_M][THREAD_TILE_N];
    #pragma unroll
    for (int i = 0; i < THREAD_TILE_M; ++i) {
        #pragma unroll
        for (int j = 0; j < THREAD_TILE_N; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    int row_start = ty * THREAD_TILE_M;
    int col_start = tx * THREAD_TILE_N;
    #pragma unroll
    for (int k = 0; k < KT; ++k) {
        float4 breg4_0 = *reinterpret_cast<const float4*>(&sB[k * (TILE_N + 4) + col_start]);
        float4 breg4_1 = *reinterpret_cast<const float4*>(&sB[k * (TILE_N + 4) + col_start + 4]);
        float breg[THREAD_TILE_N];
        breg[0] = breg4_0.x;
        breg[1] = breg4_0.y;
        breg[2] = breg4_0.z;
        breg[3] = breg4_0.w;
        breg[4] = breg4_1.x;
        breg[5] = breg4_1.y;
        breg[6] = breg4_1.z;
        breg[7] = breg4_1.w;
        #pragma unroll
        for (int i = 0; i < THREAD_TILE_M; ++i) {
            float aval = sA[(row_start + i) * KT + k];
            #pragma unroll
            for (int j = 0; j < THREAD_TILE_N; ++j) {
                acc[i][j] += aval * breg[j];
            }
        }
    }
    #pragma unroll
    for (int i = 0; i < THREAD_TILE_M; ++i) {
        int global_row = row_base + row_start + i;
        if (global_row < M) {
            int global_col0 = col_base + col_start;
            if (global_col0 + THREAD_TILE_N - 1 < M) {
                float4 c0 = make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
                float4 c1 = make_float4(acc[i][4], acc[i][5], acc[i][6], acc[i][7]);
                __stcs(reinterpret_cast<float4*>(&C[global_row * M + global_col0]), c0);
                __stcs(reinterpret_cast<float4*>(&C[global_row * M + global_col0 + 4]), c1);
            } else {
                #pragma unroll
                for (int j = 0; j < THREAD_TILE_N; ++j) {
                    int global_col = global_col0 + j;
                    if (global_col < M) {
                        __stcs(&C[global_row * M + global_col], acc[i][j]);
                    }
                }
            }
        }
    }
}
// Generic (runtime-K) fallback kernel, used when K does not match one of the
// specialized template instantiations below.
__global__ void tall_skinny_matmul_kernel_generic(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K)
{
    extern __shared__ float smem[];
    float* sA = smem;
    float* sB = smem + TILE_M * K;
    int row_base = blockIdx.x * TILE_M;
    int col_base = blockIdx.y * TILE_N;
    int tid = threadIdx.x;
    int tx = tid % THREADS_X;
    int ty = tid / THREADS_X;
    if (K % VEC == 0) {
        const int k_groups = K / VEC;
        for (int idx = tid; idx < TILE_M * k_groups; idx += NUM_THREADS) {
            int r = idx / k_groups;
            int kg = idx % k_groups;
            int global_row = row_base + r;
            if (global_row < M) {
                float4 avec = *reinterpret_cast<const float4*>(&A[global_row * K + kg * VEC]);
                sA[r * K + kg * VEC + 0] = avec.x;
                sA[r * K + kg * VEC + 1] = avec.y;
                sA[r * K + kg * VEC + 2] = avec.z;
                sA[r * K + kg * VEC + 3] = avec.w;
            } else {
                sA[r * K + kg * VEC + 0] = 0.0f;
                sA[r * K + kg * VEC + 1] = 0.0f;
                sA[r * K + kg * VEC + 2] = 0.0f;
                sA[r * K + kg * VEC + 3] = 0.0f;
            }
        }
    } else {
        for (int idx = tid; idx < TILE_M * K; idx += NUM_THREADS) {
            int r = idx / K;
            int k = idx % K;
            int global_row = row_base + r;
            sA[r * K + k] = (global_row < M) ? A[global_row * K + k] : 0.0f;
        }
    }
    const int col_groups = TILE_N / VEC;
    for (int idx = tid; idx < K * col_groups; idx += NUM_THREADS) {
        int k = idx / col_groups;
        int cg = idx % col_groups;
        int col = col_base + cg * VEC;
        if (col + VEC - 1 < M) {
            float4 bvec = *reinterpret_cast<const float4*>(&B[k * M + col]);
            sB[k * (TILE_N + 4) + cg * VEC + 0] = bvec.x;
            sB[k * (TILE_N + 4) + cg * VEC + 1] = bvec.y;
            sB[k * (TILE_N + 4) + cg * VEC + 2] = bvec.z;
            sB[k * (TILE_N + 4) + cg * VEC + 3] = bvec.w;
        } else {
            #pragma unroll
            for (int c = 0; c < VEC; ++c) {
                int cc = col + c;
                sB[k * (TILE_N + 4) + cg * VEC + c] = (cc < M) ? B[k * M + cc] : 0.0f;
            }
        }
    }
    __syncthreads();
    float acc[THREAD_TILE_M][THREAD_TILE_N];
    #pragma unroll
    for (int i = 0; i < THREAD_TILE_M; ++i) {
        #pragma unroll
        for (int j = 0; j < THREAD_TILE_N; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    int row_start = ty * THREAD_TILE_M;
    int col_start = tx * THREAD_TILE_N;
    for (int k = 0; k < K; ++k) {
        float4 breg4_0 = *reinterpret_cast<const float4*>(&sB[k * (TILE_N + 4) + col_start]);
        float4 breg4_1 = *reinterpret_cast<const float4*>(&sB[k * (TILE_N + 4) + col_start + 4]);
        float breg[THREAD_TILE_N];
        breg[0] = breg4_0.x;
        breg[1] = breg4_0.y;
        breg[2] = breg4_0.z;
        breg[3] = breg4_0.w;
        breg[4] = breg4_1.x;
        breg[5] = breg4_1.y;
        breg[6] = breg4_1.z;
        breg[7] = breg4_1.w;
        #pragma unroll
        for (int i = 0; i < THREAD_TILE_M; ++i) {
            float aval = sA[(row_start + i) * K + k];
            #pragma unroll
            for (int j = 0; j < THREAD_TILE_N; ++j) {
                acc[i][j] += aval * breg[j];
            }
        }
    }
    #pragma unroll
    for (int i = 0; i < THREAD_TILE_M; ++i) {
        int global_row = row_base + row_start + i;
        if (global_row < M) {
            int global_col0 = col_base + col_start;
            if (global_col0 + THREAD_TILE_N - 1 < M) {
                float4 c0 = make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
                float4 c1 = make_float4(acc[i][4], acc[i][5], acc[i][6], acc[i][7]);
                __stcs(reinterpret_cast<float4*>(&C[global_row * M + global_col0]), c0);
                __stcs(reinterpret_cast<float4*>(&C[global_row * M + global_col0 + 4]), c1);
            } else {
                #pragma unroll
                for (int j = 0; j < THREAD_TILE_N; ++j) {
                    int global_col = global_col0 + j;
                    if (global_col < M) {
                        __stcs(&C[global_row * M + global_col], acc[i][j]);
                    }
                }
            }
        }
    }
}
template <int KT>
static void launch_tpl(const float* A, const float* B, float* C, int M, dim3 grid, dim3 block, size_t shmem_bytes) {
    if (shmem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(tall_skinny_matmul_kernel_tpl<KT>,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             (int)shmem_bytes);
    }
    tall_skinny_matmul_kernel_tpl<KT><<<grid, block, shmem_bytes>>>(A, B, C, M);
}
torch::Tensor tall_skinny_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    TORCH_CHECK(B.size(0) == K, "Inner dimensions must match");
    TORCH_CHECK(B.size(1) == M, "Output must be square (M x M) for this kernel");
    TORCH_CHECK(K <= MAX_K, "K too large for shared memory buffer");
    auto C = torch::empty({M, M}, A.options());
    dim3 block(NUM_THREADS);
    dim3 grid((M + TILE_M - 1) / TILE_M, (M + TILE_N - 1) / TILE_N);
    size_t shmem_bytes = (size_t)(TILE_M * K + K * (TILE_N + 4)) * sizeof(float);
    switch (K) {
        case 16:
            launch_tpl<16>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, grid, block, shmem_bytes);
            break;
        case 32:
            launch_tpl<32>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, grid, block, shmem_bytes);
            break;
        case 64:
            launch_tpl<64>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, grid, block, shmem_bytes);
            break;
        case 128:
            launch_tpl<128>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, grid, block, shmem_bytes);
            break;
        default:
            if (shmem_bytes > 48 * 1024) {
                cudaFuncSetAttribute(tall_skinny_matmul_kernel_generic,
                                     cudaFuncAttributeMaxDynamicSharedMemorySize,
                                     (int)shmem_bytes);
            }
            tall_skinny_matmul_kernel_generic<<<grid, block, shmem_bytes>>>(
                A.data_ptr<float>(),
                B.data_ptr<float>(),
                C.data_ptr<float>(),
                M, K
            );
            break;
    }
    return C;
}
